python3 -c "
import json

# Extract 2020-2024 data from 2025 bulletin
with open('/app/resources/treasury_bulletin_2025_09.json', 'r') as f:
    data = json.load(f)

for elem in data['document']['elements']:
    if elem['type'] == 'table':
        content = str(elem.get('content', ''))
        if '2019' in content and '2020' in content and '2024' in content and 'Total receipts' in content:
            lines = content.split('<tr>')
            for line in lines:
                if '<td>201' in line or '<td>202' in line:
                    print(line[:1000])
                    print('---')
            break
"
